  "خير الدعاء دعاء يوم عرفة — رواه الترمذي": {en:"The best supplication is the supplication of the Day of Arafah — narrated by al-Tirmidhi",fr:"La meilleure invocation est celle du jour d'Arafa — rapporté par at-Tirmidhî",id:"Doa terbaik adalah doa hari Arafah — diriwayatkan At-Tirmidzi",ur:"بہترین دعا یومِ عرفہ کی دعا ہے — ترمذی نے روایت کیا",bn:"শ্রেষ্ঠ দোয়া আরাফার দিনের দোয়া — তিরমিজি বর্ণনা করেন",tr:"Duanın en hayırlısı Arefe Günü duasıdır — Tirmizî rivayet etti"},
  "دعاء العفو": {en:"The supplication of pardon",fr:"L'invocation du pardon",id:"Doa ampunan",ur:"دعائے عفو",bn:"ক্ষমার দোয়া",tr:"Af duası"},
  "اللهم إنك عفو...": {en:"O God, You are Forgiving…",fr:"Ô Dieu, Tu es Pardonneur…",id:"Ya Allah, Engkau Maha Pengampun…",ur:"اے اللہ! تو معاف کرنے والا ہے…",bn:"হে আল্লাহ, তুমি ক্ষমাশীল…",tr:"Allah'ım, Sen Affedensin…"},
  "دعاء الصلاح": {en:"The supplication of soundness",fr:"L'invocation de la rectitude",id:"Doa kebaikan",ur:"دعائے صلاح",bn:"উত্তমতার দোয়া",tr:"Salâh duası"},
  "اللهم أصلح لي...": {en:"O God, set right for me…",fr:"Ô Dieu, améliore pour moi…",id:"Ya Allah, perbaiki untukku…",ur:"اے اللہ! میرے لیے درست فرما…",bn:"হে আল্লাহ, আমার জন্য ঠিক করে দাও…",tr:"Allah'ım, benim için düzelt…"},
  "للوالدين والأمة": {en:"For parents and the community",fr:"Pour les parents et la communauté",id:"Untuk orang tua dan umat",ur:"والدین اور امت کے لیے",bn:"পিতা-মাতা ও উম্মতের জন্য",tr:"Anne baba ve ümmet için"},
  "اللهم اغفر لي...": {en:"O God, forgive me…",fr:"Ô Dieu, pardonne-moi…",id:"Ya Allah, ampunilah aku…",ur:"اے اللہ! مجھے بخش…",bn:"হে আল্লাহ, আমাকে ক্ষমা করো…",tr:"Allah'ım, beni bağışla…"},
  "تثبيت القلب": {en:"Steadying the heart",fr:"Affermir le cœur",id:"Meneguhkan hati",ur:"دل کا ثبات",bn:"হৃদয় অবিচল",tr:"Kalbi sabitlemek"},
  "اللهم يا مقلب...": {en:"O God, O Turner of hearts…",fr:"Ô Dieu, Toi qui fais tourner les cœurs…",id:"Ya Allah, Yang Membolak-balikkan hati…",ur:"اے اللہ! دلوں کو پھیرنے والے…",bn:"হে আল্লাহ, হৃদয় পরিবর্তনকারী…",tr:"Allah'ım, kalpleri çeviren…"},
